(window.__quranSurahs=window.__quranSurahs||{})[114]={"nomPhon":"An-Naas","versets":{"1":{"text":"Dis: «Je cherche protection auprès du Seigneur des hommes.","arabe":"قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ"},"2":{"text":"Le Souverain des hommes,","arabe":"مَلِكِ ٱلنَّاسِ"},"3":{"text":"Dieu des hommes,","arabe":"إِلَٰهِ ٱلنَّاسِ"},"4":{"text":"contre le mal du mauvais conseiller, furtif,","arabe":"مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ"},"5":{"text":"qui souffle le mal dans les poitrines des hommes,","arabe":"ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ"},"6":{"text":"qu'il (le conseiller) soit un djinn, ou un être humain».","arabe":"مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ"}}};